function useTypewriter(words) {
  const [text, setText] = useState("");
  const idx = useRef(0), ci = useRef(0), del = useRef(false);
  useEffect(() => {
    let t;
    const tick = () => {
      const w = words[idx.current];
      if (!del.current) { setText(w.slice(0, ++ci.current)); if (ci.current > w.length) { del.current = true; t = setTimeout(tick, 1300); return; } }
      else { setText(w.slice(0, --ci.current)); if (ci.current <= 0) { del.current = false; idx.current = (idx.current + 1) % words.length; } }
      t = setTimeout(tick, del.current ? 55 : 95);
    };
    t = setTimeout(tick, 95);
    return () => clearTimeout(t);
  }, []);
  return text;
}

function useReveal() {
  useEffect(() => {
    const obs = new IntersectionObserver(entries => { entries.forEach(e => { if (e.isIntersecting) e.target.classList.add("vis"); }); }, { threshold: 0.1 });
    document.querySelectorAll(".rv").forEach(el => obs.observe(el));
    return () => obs.disconnect();
  }, []);
}

function useParticles(canvasRef) {
  useEffect(() => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext("2d"); let id;
    const resize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    resize(); window.addEventListener("resize", resize);
    const pts = Array.from({length:55}, () => ({
      x: Math.random() * window.innerWidth, y: Math.random() * window.innerHeight,
      r: Math.random() * 1.2 + 0.3, dx: (Math.random()-0.5)*0.22, dy: (Math.random()-0.5)*0.22,
      o: Math.random()*0.3+0.1,
    }));
    const draw = () => {
      ctx.clearRect(0,0,canvas.width,canvas.height);
      const g1 = ctx.createRadialGradient(canvas.width*0.15,canvas.height*0.25,0,canvas.width*0.15,canvas.height*0.25,380);
      g1.addColorStop(0,"rgba(139,94,60,0.07)"); g1.addColorStop(1,"transparent");
      ctx.fillStyle=g1; ctx.fillRect(0,0,canvas.width,canvas.height);
      const g2 = ctx.createRadialGradient(canvas.width*0.85,canvas.height*0.75,0,canvas.width*0.85,canvas.height*0.75,320);
      g2.addColorStop(0,"rgba(196,154,108,0.06)"); g2.addColorStop(1,"transparent");
      ctx.fillStyle=g2; ctx.fillRect(0,0,canvas.width,canvas.height);
      pts.forEach(p => {
        ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
        ctx.fillStyle=`rgba(139,94,60,${p.o})`; ctx.fill();
        p.x+=p.dx; p.y+=p.dy;
        if(p.x<0||p.x>canvas.width) p.dx*=-1;
        if(p.y<0||p.y>canvas.height) p.dy*=-1;
      });
      for(let i=0;i<pts.length;i++) for(let j=i+1;j<pts.length;j++){
        const dx=pts[i].x-pts[j].x, dy=pts[i].y-pts[j].y, d=Math.sqrt(dx*dx+dy*dy);
        if(d<100){ ctx.beginPath(); ctx.moveTo(pts[i].x,pts[i].y); ctx.lineTo(pts[j].x,pts[j].y); ctx.strokeStyle=`rgba(139,94,60,${0.05*(1-d/100)})`; ctx.lineWidth=0.5; ctx.stroke(); }
      }
      id = requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(id); window.removeEventListener("resize",resize); };
  }, []);
}

function useCursor() {
  const dotRef = useRef(null), ringRef = useRef(null);
  const rx = useRef(0), ry = useRef(0), mx = useRef(0), my = useRef(0);
  useEffect(() => {
    const onMove = e => { mx.current=e.clientX; my.current=e.clientY; };
    document.addEventListener("mousemove", onMove);
    let id;
    const loop = () => {
      if(dotRef.current) dotRef.current.style.transform=`translate(${mx.current-5}px,${my.current-5}px)`;
      rx.current += (mx.current-rx.current)*0.12; ry.current += (my.current-ry.current)*0.12;
      if(ringRef.current) ringRef.current.style.transform=`translate(${rx.current-16}px,${ry.current-16}px)`;
      id = requestAnimationFrame(loop);
    };
    loop();
    return () => { document.removeEventListener("mousemove",onMove); cancelAnimationFrame(id); };
  }, []);
  return {dotRef, ringRef};
}

function SH({label, title, accent}) {
  return (
    <div className="rv">
      <p className="sec-lbl">// {label}</p>
      <h2 className="sec-ttl">{title} <span className="g">{accent}</span></h2>
    </div>
  );
}

